import{_ as t,o as r,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"科学日报 · 2026-11-05（AI系统架构 · 5 篇：潜动作/持久压制/投机推理/ICL 电路/无知几何）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-11-05-ai.md","filePath":"topics/ai-system-architecture/science-daily-2026-11-05-ai.md"}'),i={name:"topics/ai-system-architecture/science-daily-2026-11-05-ai.md"};function e(g,o,a,c,l,d){return r(),s("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-11-05-ai系统架构-·-5-篇-潜动作-持久压制-投机推理-icl-电路-无知几何" tabindex="-1">科学日报 · 2026-11-05（AI系统架构 · 5 篇：潜动作/持久压制/投机推理/ICL 电路/无知几何） <a class="header-anchor" href="#科学日报-·-2026-11-05-ai系统架构-·-5-篇-潜动作-持久压制-投机推理-icl-电路-无知几何" aria-label="Permalink to &quot;科学日报 · 2026-11-05（AI系统架构 · 5 篇：潜动作/持久压制/投机推理/ICL 电路/无知几何）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> — 第55期 ｜ AI 板块（5 篇，全部 arXiv cs.AI/cs.LG，2026-11-03） 落盘说明：文件名带 <code>-ai</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-05-ai-·-1-5-dreamx——把视频扩散模型改造成通用「潜动作」学习器" tabindex="-1">科学日报 2026-11-05（AI · 1/5）：DreamX——把视频扩散模型改造成通用「潜动作」学习器 <a class="header-anchor" href="#科学日报-2026-11-05-ai-·-1-5-dreamx——把视频扩散模型改造成通用「潜动作」学习器" aria-label="Permalink to &quot;科学日报 2026-11-05（AI · 1/5）：DreamX——把视频扩散模型改造成通用「潜动作」学习器&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ arXiv: 2611.05377 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：从视频学<strong>通用动作表示</strong>，要求捕捉<strong>同一动作不同执行下一致的动力学</strong>、又对<strong>具身与外观变化不变</strong>；既有<strong>潜动作模型</strong>常把动作与无关视觉变化<strong>纠缠</strong>，限制<strong>跨具身迁移</strong>。</li><li>方法：把<strong>预训练视频扩散模型</strong>当<strong>通用潜动作学习器</strong>——从其时空特征抽<strong>紧凑潜动作</strong>，把每个潜视频帧<strong>压缩 300×（1,200→4 token）</strong>；借助<strong>生成先验</strong>让潜动作<strong>与视觉外观解耦</strong>。</li><li>结果（实测）： <ul><li><strong>LARY-Bench</strong> 上取得潜动作模型 <strong>SOTA</strong>；</li><li>潜空间成为<strong>跨具身（人/机器人）、跨环境、跨动作参数化</strong>的<strong>共享动作接口</strong>：支持<strong>任意到任意视频迁移</strong>与<strong>零样本跨具身动作迁移</strong>；</li><li>让<strong>策略在紧凑潜动作空间学习</strong>，<strong>降低视频扩散策略的算力</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>robotics</code>）： <ol><li><strong>「先压掉不相关的自由度，动作的『不变量』自己浮出来」</strong>——把帧压到 4 token 不是为省算力，而是<strong>强迫表示只留动作相关动力学</strong>；判据：<strong>要学『与具身无关的共性』时，主动用压缩/瓶颈去掉外观噪声</strong>（呼应母题「<strong>约束-涌现</strong>」）。</li><li><strong>「让现成的大模型当『接口』而非重训专用模型」</strong>——复用视频扩散的生成先验做动作接口；与库内 <code>topics/ai-system-architecture/</code> 的「复用既有能力做新接口」一脉。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-05-ai-·-2-5-pearl——让「不想要的行为」被压制得更持久" tabindex="-1">科学日报 2026-11-05（AI · 2/5）：PEARL——让「不想要的行为」被压制得更持久 <a class="header-anchor" href="#科学日报-2026-11-05-ai-·-2-5-pearl——让「不想要的行为」被压制得更持久" aria-label="Permalink to &quot;科学日报 2026-11-05（AI · 2/5）：PEARL——让「不想要的行为」被压制得更持久&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ arXiv: 2611.05358 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：不良行为可在<strong>训练任何阶段出现或复现</strong>，<strong>观测到之后能多有效地压制它</strong>（且<strong>经得起后续训练</strong>）？</li><li>方法：先造两个刻意失准的**「模式生物」<strong>——<strong>窄触发型</strong>（仅提示含特定线索时才作弊）与</strong>宽触发型**（在<strong>不安全代码</strong>上微调后广泛有害）；把<strong>事后行为压制</strong>形式化，沿<strong>即时压制 / 进一步训练下的持久性 / 通用能力保持</strong>评估 <strong>SFT、GRPO、梯度上升式遗忘</strong>；提出 <strong>PEARL（Prefix-Expanded Adversarial RL）</strong>——用<strong>缓存轨迹中间状态的续写</strong>扩充 rollout 的 GRPO 变体。</li><li>结果（实测）： <ul><li>基于「<strong>对齐浅层性</strong>」，作者假设<strong>更持久的压制需要能从更广的失准状态恢复</strong>；</li><li>在<strong>两个模式生物 + 两个模型族（Qwen3-4B、GPT-OSS-20B）<strong>上，PEARL <strong>即时压制强、保住任务准确率</strong>，且在</strong>进一步微调（模式生物数据或无关数据）下仍持久</strong>；</li><li>当不良行为「<strong>宽</strong>」、<strong>无法靠定向 SFT 解决</strong>时<strong>收益最大</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「压制要治『状态族』而非『一个触发点』」</strong>——窄触发可靠定向 SFT，宽触发不行；<strong>持久压制要覆盖更广的失准中间状态</strong>；判据：<strong>当想根除某行为时，问『它只在一点出现，还是一族状态都会滑向它』</strong>（呼应母题「<strong>环境结构 &gt; 个体微调</strong>」）。</li><li><strong>「持久性必须用『再训练后会不会复发』来证，而非训完当场测」</strong>——判据：<strong>对齐声明要给『后续训练下不复现』的端到端证据</strong>（呼应母题「<strong>外部信号 &gt; 自评分 / 否证性判据</strong>」）。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-05-ai-·-3-5-对抗式投机推理——把投机解码从「加速器」变成「上下文精度分配器」" tabindex="-1">科学日报 2026-11-05（AI · 3/5）：对抗式投机推理——把投机解码从「加速器」变成「上下文精度分配器」 <a class="header-anchor" href="#科学日报-2026-11-05-ai-·-3-5-对抗式投机推理——把投机解码从「加速器」变成「上下文精度分配器」" aria-label="Permalink to &quot;科学日报 2026-11-05（AI · 3/5）：对抗式投机推理——把投机解码从「加速器」变成「上下文精度分配器」&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ arXiv: 2611.05345 ｜ arXiv cs.AI (2026)</p></blockquote><ul><li>问题：<strong>投机解码</strong>一直被视为<strong>纯系统优化</strong>（不改变模型行为），因此训练草稿模型只盯<strong>接受率</strong>；但在<strong>长程智能体推理</strong>中，这个前提是否成立？</li><li>方法：在<strong>复杂智能体任务</strong>上测量<strong>前沿开源权重模型</strong>在不同投机解码下的表现；进而<strong>训练草稿模型偏好对抗性偏好</strong>（在关键决策点<strong>被拒绝</strong>），使验证在那些点<strong>重启</strong>、关键思考 token 由<strong>目标模型在其最小噪声条件下</strong>采样。</li><li>结果（实测）： <ul><li><strong>验证窗口内数值噪声累积</strong>，<strong>草稿接受结果会在 30 步后改变输出分布</strong>，<strong>随机方向地</strong>显著影响长程推理准确率（「37 步」量级的漂移）；</li><li>训练后：<strong>复杂智能体编码基准上端到端成功率提升</strong>，<strong>不动目标模型或其输出分布</strong>，仅训练 <strong>0.06%–0.28%</strong> 托管参数。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code>）： <ol><li><strong>「被当成『无损加速』的近似，在长程上其实是有损且有偏的」</strong>——短程看不出、长程放大；判据：<strong>任何『近似等价』的假设，都要在长程/多次迭代下重测是否仍等价</strong>（呼应母题「<strong>外部信号 &gt; 自评分</strong>」——用端到端成功率而非接受率收口）。</li><li><strong>「把关键决策『重新交给最可信的模块』」</strong>——训练草稿在决策点退让，让<strong>目标模型在低噪声条件下</strong>决定关键 token；判据：<strong>想让关键步骤更可靠，就让负责它的组件回到噪声最低的状态</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-05-ai-·-4-5-上下文学习-icl-的因果电路" tabindex="-1">科学日报 2026-11-05（AI · 4/5）：上下文学习（ICL）的因果电路 <a class="header-anchor" href="#科学日报-2026-11-05-ai-·-4-5-上下文学习-icl-的因果电路" aria-label="Permalink to &quot;科学日报 2026-11-05（AI · 4/5）：上下文学习（ICL）的因果电路&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ arXiv: 2611.05344 ｜ arXiv cs.LG (2026)</p></blockquote><ul><li>问题：<strong>ICL</strong> 让模型按提示示例完成任务、<strong>无需改参数</strong>；当标签<strong>任意</strong>时，模型必须<strong>在前向传播内</strong>学会一个它不可能记住的映射。此前找到<strong>候选部件</strong>，但<strong>没讲清它们如何组合</strong>。</li><li>方法：在三个 <strong>3–4B 参数 Transformer</strong> 上，用<strong>激活 patch、头消融对随机头基线、模型自身信号 steering</strong> 逐个因果确立各步，并用<strong>单提示分布拟合的 softmax 读出模型</strong>去预测另一分布。</li><li>结果（实测）： <ul><li>模型在<strong>标签 token 位置实现键值记忆</strong>：每个标签 token 的<strong>残差流编码标签身份</strong>，<strong>中层注意力头把前一个示例的类别写成它的键</strong>；<strong>上层头把查询类别与已存键匹配、复制出对应标签</strong>；</li><li><strong>早期层信号</strong>（编码是否有标签重复）<strong>门控读出</strong>，缺失时只注意提示开头、不偏向标签；<strong>另一组头抑制最近出现的标签</strong>；</li><li>计算在<strong>三个模型间守恒</strong>，<strong>从头训练的 Transformer 会长出相同部件</strong>，且该电路<strong>可迁移到语义概念与有意义的标签</strong>。</li></ul></li><li>洞察（对本库 <code>ai-system-architecture</code> × <code>ai-brain</code>）： <ol><li><strong>「把『涌现能力』拆成可指认的部件与接线」</strong>——ICL 不是玄学，是<strong>门控的关联查找（gated associative lookup）</strong>；判据：<strong>遇到『模型竟能…』时，先问『哪些部件、以什么顺序、被什么门控』</strong>。</li><li><strong>「因果确立（patch/消融/steering）+ 可迁移 + 从头复现」是机制解释的三重证据</strong>——判据：<strong>声称『找到了机制』时，要求它同时满足因果、跨模型守恒、从零复现</strong>（呼应母题「<strong>否证性判据优于肯定性判据</strong>」）。</li></ol></li></ul><hr><h2 id="科学日报-2026-11-05-ai-·-5-5-无知几何——用激活碎片化检测-llm-被压制-但仍可恢复-的知识" tabindex="-1">科学日报 2026-11-05（AI · 5/5）：无知几何——用激活碎片化检测 LLM 被压制（但仍可恢复）的知识 <a class="header-anchor" href="#科学日报-2026-11-05-ai-·-5-5-无知几何——用激活碎片化检测-llm-被压制-但仍可恢复-的知识" aria-label="Permalink to &quot;科学日报 2026-11-05（AI · 5/5）：无知几何——用激活碎片化检测 LLM 被压制（但仍可恢复）的知识&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ arXiv: 2611.05272 ｜ arXiv cs.LG (2026)</p></blockquote><ul><li>问题：判断 LLM 是否「<strong>真的知道</strong>」某概念是根本难题：<strong>行为指标会被压制欺骗</strong>——<strong>拒答的模型可能仍藏有可恢复的知识</strong>。</li><li>方法：度量 <strong>anon-vectors 的几何一致性</strong>（概念专属查询与其<strong>匿名改写</strong>之间隐状态的差）——<strong>真实知识形成紧致、低熵的簇</strong>，<strong>无知导致几何碎片化</strong>；在<strong>十一个指令微调 LLM（三族）<strong>上验证，并与</strong>遗忘后对抗恢复</strong>对照、做<strong>逐层分析</strong>。</li><li>结果（实测）： <ul><li>所有<strong>碎片化指标都能可靠区分已知/未知概念</strong>；</li><li><strong>遗忘后</strong>，碎片化几何与<strong>四类攻击、五种遗忘算法</strong>下的<strong>对抗恢复</strong>相关（方向取决于攻击方法）；</li><li><strong>逐层分析</strong>显示不同对抗机制在<strong>不同深度</strong>利用该几何，呈现<strong>行为评估看不到的高攻击特异相关性</strong>；</li><li>提供<strong>单相位、免攻击</strong>的<strong>遗忘稳健性代理指标</strong>，捕捉输出层指标无法触及的参数化知识。</li></ul></li><li>洞察（对本库 <code>ai-brain</code> × <code>ai-system-architecture</code> × <code>cybersecurity</code>）： <ol><li><strong>「『不知道』和『被压着不说』在行为上看不出，但在内部几何上分得开」</strong>——判据：<strong>当行为层无法区分两种状态时，去内部表示里找结构性差异</strong>（呼应母题「<strong>外部信号 &gt; 自评分</strong>」与 <code>topics/ai-brain</code> 的 <strong>Echo Gap</strong>：自报告不可信，要用与内容去相关的信号）。</li><li><strong>「免攻击的代理指标可以预测对抗稳健性」</strong>——单相位即估<strong>遗忘稳健性</strong>；判据：<strong>想预测某防御在对抗下的表现时，先找一个不依赖攻击的几何/结构代理</strong>。</li><li><strong>与库内呼应</strong>：与 <code>topics/ai-system-architecture/science-daily-2026-10-26-ai.md</code> 的「PIR 读出模型隐瞒的知识」、<code>topics/cybersecurity/</code>「口头拒绝 ≠ 真实执行」同族——<strong>拒答/遗忘是表型，真知识是基因型</strong>。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ <code>topics/cybersecurity/index.md</code> ｜ 第55期 AI 板块</p></blockquote><p>关键词：科学日报第55期、DreamX、视频扩散模型、通用潜动作学习器universal latent action learner、帧压缩300倍、跨具身共享动作接口、LARY-Bench、零样本跨具身动作迁移、PEARL、事后行为压制post-hoc behavioral suppression、对齐浅层性alignment shallowness、窄触发宽触发模式生物、GRPO、Prefix-Expanded Adversarial RL、Qwen3-4B、GPT-OSS-20B、对抗式投机推理、投机解码speculative decoding、验证窗口数值噪声、30步后改变输出分布、拒绝草稿模型、上下文精度分配器、动0.06-0.28%参数、A Circuit for In-Context Learning、ICL、键值记忆、标签token残差流、中层写键上层匹配读出、早期门控、抑制最近标签、激活patch头消融steering、从头训练复现、Geometry of Ignorance、anon-vectors、激活碎片化activation fragmentation、紧致低熵簇vs几何碎片化、被压制的知识、遗忘稳健性代理指标、拒答不等于不知道、免攻击指标、Echo Gap、外部信号大于自评分、否证性判据优于肯定性判据、环境结构大于个体微调、约束涌现、改路径优于加力度</p><p>关联：<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-system-architecture/science-daily-2026-11-04-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-11-03-ai.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-26-ai.md</code>、<code>topics/cybersecurity/science-daily-2026-11-04.md</code>、<code>topics/ai-brain/index.md</code>、<code>ScienceDaily/daily/2026-11-05.md</code></p>',26)])])}const m=t(i,[["render",e]]);export{h as __pageData,m as default};
